/* Parameter names, selector labels, MIDI CCs and value display, after jupiter8_esp32/src/dsp/params.cpp.
 * Integers only: the values come from tables generated by tools/gen_ju_tables.py. */
#include "ju_params.h"
#include "ju_tables.h"

typedef struct {
    const char *shortName;          /* up to 3 characters, under the control */
    const char *longName;           /* the readout at the bottom of the screen */
    uint8_t steps;                  /* 0 = continuous 0-255; otherwise a selector with this many values */
    const char *const *labels;
    uint8_t cc;                     /* MIDI CC, 0 = none */
} ju_pinfo_t;

