const char *ju_pshort(int id) { return kInfo[id].shortName; }
const char *ju_plong(int id) { return kInfo[id].longName; }
int ju_psteps(int id) { return kInfo[id].steps; }
const char *ju_plabel(int id, int v) { return kInfo[id].labels[v]; }
int ju_cc_to_param(uint8_t cc)
{
    int i;
    if (cc == 0) return -1;
    for (i = 0; i < P_COUNT + G_COUNT; i++)
        if (kInfo[i].cc == cc) return i;
    return -1;
}

/* ---- display */
static char *put_str(char *o, char *e, const char *s) { while (*s && o < e) *o++ = *s++; return o; }
static char *put_int(char *o, char *e, int v, int plus)
{
    char t[12];
    int n = 0;
    unsigned u = v < 0 ? 0u - (unsigned)v : (unsigned)v;
    if (v < 0 && o < e) *o++ = '-'; else if (plus && o < e) *o++ = '+';
    do { t[n++] = (char)('0' + u % 10u); u /= 10u; } while (u);
    while (n && o < e) *o++ = t[--n];
    return o;
}
static char *put_fix(char *o, char *e, uint32_t v, int dec)     /* v / 10^dec with dec decimals */
{
    uint32_t p = dec == 1 ? 10u : 100u;
    o = put_int(o, e, (int)(v / p), 0);
    if (o < e) *o++ = '.';
    if (dec == 2 && o < e) *o++ = (char)('0' + (v / 10u) % 10u);
    if (o < e) *o++ = (char)('0' + v % 10u);
    return o;
}
static char *put_time(char *o, char *e, uint32_t us)           /* "123 ms", or "1.23 s" from a second up */
{
    if (us < 1000000u) {
        o = put_int(o, e, (int)((us + 500u) / 1000u), 0);
        return put_str(o, e, " ms");
    }
    o = put_fix(o, e, (us + 5000u) / 10000u, 2);
    return put_str(o, e, " s");
}
static char *put_hz(char *o, char *e, uint32_t hz100)           /* Hz x100: "123 Hz" or "1.23 kHz" */
{
    if (hz100 < 100000u) {
        o = put_int(o, e, (int)((hz100 + 50u) / 100u), 0);
        return put_str(o, e, " Hz");
    }
    o = put_fix(o, e, (hz100 + 500u) / 1000u, 2);
    return put_str(o, e, " kHz");
}
static char *put_cents(char *o, char *e, int v)                 /* (v - 128) * 50 / 127, with its sign even at 0 */
{
    int d = v - 128, m = d < 0 ? -d : d;
    if (o < e) *o++ = d < 0 ? '-' : '+';
    o = put_int(o, e, (m * 100 + 127) / 254, 0);
    return put_str(o, e, " cent");
}
static int pct_of(int v, int full) { return (v * full * 2 + 255) / 510; }   /* v / 255 * full, rounded */

void ju_format_param(int id, uint8_t v, char *out, int n)
{
    char *o = out, *e = out + n - 1;
    static const char *const kNotes[] = {"C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"};
    const ju_pinfo_t *pi = &kInfo[id];
    if (pi->steps) {
        int i = v < pi->steps ? v : pi->steps - 1;
        o = put_str(o, e, pi->labels[i]);
        *o = 0;
        return;
    }
    switch (id) {
    case P_LFO_RATE: o = put_str(put_fix(o, e, JU_D_LFO[v], 2), e, " Hz"); break;
    case P_LFO_DELAY: o = put_time(o, e, JU_D_DLY[v]); break;
    case P_VM_LFO: o = put_str(put_fix(o, e, JU_D_VLO[v], 2), e, " oct"); break;
    case P_VM_ENV: o = put_str(put_fix(o, e, JU_D_VEO[v], 2), e, " oct"); break;
    case P_V1_XMOD: o = put_str(put_fix(o, e, JU_D_XM[v], 2), e, " oct"); break;
    case P_V2_TUNE: o = put_cents(o, e, v); break;
    case P_HPF: o = put_hz(o, e, JU_D_HPF[v]); break;
    case P_VCF_CUT: o = put_hz(o, e, JU_D_CUT[v]); break;
    case P_VCF_ENV: o = put_str(put_fix(o, e, JU_D_VFE[v], 1), e, " oct"); break;
    case P_VCF_LFO: o = put_str(put_fix(o, e, JU_D_VFL[v], 2), e, " oct"); break;
    case P_VCF_KEY: o = put_str(put_int(o, e, pct_of(v, 120), 0), e, " %"); break;
    case P_E1_A: case P_E2_A: o = put_time(o, e, JU_D_ATT[v]); break;
    case P_E1_D: case P_E1_R: case P_E2_D: case P_E2_R: o = put_time(o, e, JU_D_DEC[v]); break;
    case P_COUNT + G_TUNE: o = put_cents(o, e, v); break;
    case P_COUNT + G_SPLIT: o = put_str(o, e, kNotes[v % 12]); o = put_int(o, e, (int)(v / 12) - 1, 0); break;
    case P_COUNT + G_ARP_RATE: o = put_str(put_fix(o, e, JU_D_ARP[v], 1), e, " Hz"); break;
    case P_COUNT + G_PORTA_TIME: o = put_time(o, e, JU_D_POR[v]); break;
    case P_COUNT + G_TEMPO: o = put_str(put_int(o, e, 40 + (int)v, 0), e, " BPM"); break;
    case P_COUNT + G_MOD_RISE: o = put_time(o, e, JU_D_RIS[v]); break;
    default: o = put_str(put_int(o, e, pct_of(v, 100), 0), e, " %"); break;
    }
    *o = 0;
}
